slugs={
 "why":"sql-zachem-nuzhen-semeinyi-byudzhet", "model":"sql-tablica-stroka-stolbec-null",
 "schema":"sql-create-table-ogranicheniya", "insert":"sql-insert-i-parametry",
 "select":"sql-select-where-order-limit", "expressions":"sql-case-coalesce-daty",
 "aggregate":"sql-sum-count-group-by-having", "join":"sql-klyuchi-i-join",
 "cte":"sql-podzaprosy-i-cte", "windows":"sql-okonnye-funkcii",
 "transactions":"sql-tranzakcii-i-update", "audit":"sql-sverka-dannyh",
 "final":"sql-indeks-explain-backup"}
mapping_path=ROOT/"tools/course/lesson-slugs.json"
mapping=json.loads(mapping_path.read_text(encoding="utf-8"))
for stem,slug in slugs.items():
 for suffix,lang in (("","ru"),("-kz","kz"),("-en","en")):
  mapping[f"sql/{stem}{suffix}"]=[slug,lang]
mapping_path.write_text(json.dumps(mapping,ensure_ascii=False,indent=2,sort_keys=True)+"\n",encoding="utf-8")
